VALUES ('1236babf-3051-55be-bd28-3ce7ee7579ba'::uuid, '029f3de1-70b8-5b3f-9203-6f5cee8be5f5'::uuid, 0, 'Industry, Role & Course Readiness', 'In this module, the learner must use E-M0-01, E-M0-02, and E-M0-03 to identify the HN-24A progress-reporting case, the L1 support boundary, and the evidence pack contents, decide that baseline changes/EOT claims are outside role, and complete the Course Readiness Sheet fields Case ID, Allowed L1 Actions, Excluded Authority, and Evidence Pack Received. The challenge is that the dashboard-ready label may lead the learner to assume the package can be released.', '["HN-24A, A-314, 2026-07-08 review, L1 cannot approve baseline/EOT/claims"]'::jsonb, '["Safe: Record package scope, identify L1 evidence-preparation tasks, and mark approval decisions as supervisor-only.", "Risky: Start filling dashboard status before confirming role boundary and evidence pack completeness.", "Escalation: Ask planning engineer to confirm who owns baseline-change or EOT decision if the case note implies approval.", "Outside-role: approve baseline/EOT/client-ready release", "AI misuse: ask AI to complete artifact."]'::jsonb, 'In this module, the learner must use E-M0-01, E-M0-02, and E-M0-03 to identify the HN-24A progress-reporting case, the L1 support boundary, and the evidence pack contents, decide that baseline changes/EOT claims are outside role, and complete the Course Readiness Sheet fields Case ID, Allowed L1 Actions, Excluded Authority, and Evidence Pack Received. The challenge is that the dashboard-ready label may lead the learner to assume the package can be released.', '["Course entry and source case pack"]'::jsonb, '["Use E-M0-01, E-M0-02, E-M0-03 to complete Course Readiness Sheet while preserving L1 authority."]'::jsonb, 'Use before handing off to Case Intake Note in the HN-24A weekly review workflow.', '{"major_concepts": "Evidence IDs: E-M0-01, E-M0-02, E-M0-03", "key_data": "HN-24A, A-314, 2026-07-08 review, L1 cannot approve baseline/EOT/claims", "implementation_context_when_to_use": "Use before handing off to Case Intake Note in the HN-24A weekly review workflow.", "reason_behind_concept": "supports evidence-led progress, schedule and recovery-control decisions at L1."}'::jsonb, '{"ai_support_tips": "Think-first AI gate: AI unlocks only after learner writes first judgment and cites E-M0-01. Retry: Revise Allowed L1 Actions, Excluded Authority, and Evidence Pack Received after rechecking E-M0-02 role boundary and E-M0-03 evidence index."}'::jsonb, '{"evidence_ids": "E-M0-01, E-M0-02, E-M0-03", "key_data": "HN-24A, A-314, 2026-07-08 review, L1 cannot approve baseline/EOT/claims"}'::jsonb, 'At L1, complete Course Readiness Sheet using traceable project-control evidence while preserving the level decision boundary.', '{"items": ["Schedule / programme", "DPR / daily record", "progress dashboard", "evidence tracker", "recovery / escalation record", "spreadsheet artifact"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
