VALUES ('e9de3324-f4ae-5378-b8f3-f0948fa57426'::uuid, '029f3de1-70b8-5b3f-9203-6f5cee8be5f5'::uuid, 1, 'Case Intake & Role Boundary', 'In this module, the learner must use E-M1-01, E-M1-02, and E-M1-03 to identify Activity A-314, WBS 03.04, planned finish 2026-07-12, baseline planned progress 70 percent, the W27 client review trigger, and the missing planning owner, record actual progress as not yet validated, and complete Case Intake Note fields Work Object, Trigger, Confirmed Facts, Missing Information, and Role Boundary. The challenge is that the email says ''dashboard looks acceptable,'' which may lead the learner to treat dashboard progress as validated actual progress before Module 2 evidence review.', '["A-314, WBS 03.04, planned finish 2026-07-12, baseline planned 70 percent, actual progress not yet validated, planning owner blank, W27 deadline"]'::jsonb, '["Safe: Record confirmed case facts and mark owner/status gaps before evidence validation.", "Risky: Copy the dashboard summary into intake without comparing it to the schedule snapshot.", "Escalation: Flag missing recovery owner and ask the planning engineer who owns the W27 recovery action.", "Outside-role: approve baseline/EOT/client-ready release", "AI misuse: ask AI to complete artifact."]'::jsonb, 'In this module, the learner must use E-M1-01, E-M1-02, and E-M1-03 to identify Activity A-314, WBS 03.04, planned finish 2026-07-12, baseline planned progress 70 percent, the W27 client review trigger, and the missing planning owner, record actual progress as not yet validated, and complete Case Intake Note fields Work Object, Trigger, Confirmed Facts, Missing Information, and Role Boundary. The challenge is that the email says ''dashboard looks acceptable,'' which may lead the learner to treat dashboard progress as validated actual progress before Module 2 evidence review.', '["Course Readiness Sheet"]'::jsonb, '["Use E-M1-01, E-M1-02, E-M1-03 to complete Case Intake Note while preserving L1 authority."]'::jsonb, 'Use before handing off to Evidence Validation Checklist in the HN-24A weekly review workflow.', '{"major_concepts": "Evidence IDs: E-M1-01, E-M1-02, E-M1-03", "key_data": "A-314, WBS 03.04, planned finish 2026-07-12, baseline planned 70 percent, actual progress not yet validated, planning owner blank, W27 deadline", "implementation_context_when_to_use": "Use before handing off to Evidence Validation Checklist in the HN-24A weekly review workflow.", "reason_behind_concept": "supports evidence-led progress, schedule and recovery-control decisions at L1."}'::jsonb, '{"ai_support_tips": "Think-first AI gate: AI unlocks only after learner writes first judgment and cites E-M1-01. Retry: Revise Work Object, Confirmed Facts, Missing Information, and Role Boundary after rechecking E-M1-01 and E-M1-03."}'::jsonb, '{"evidence_ids": "E-M1-01, E-M1-02, E-M1-03", "key_data": "A-314, WBS 03.04, planned finish 2026-07-12, baseline planned 70 percent, actual progress not yet validated, planning owner blank, W27 deadline"}'::jsonb, 'At L1, complete Case Intake Note using traceable project-control evidence while preserving the level decision boundary.', '{"items": ["Schedule / programme", "DPR / daily record", "progress dashboard", "evidence tracker", "recovery / escalation record", "spreadsheet artifact"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
