VALUES ('08ffa87a-932d-5d92-b820-71e7b4f3b805'::uuid, '029f3de1-70b8-5b3f-9203-6f5cee8be5f5'::uuid, 2, 'Evidence & Requirement Validation', 'In this module, the learner must use E-M2-01, E-M2-02, and E-M2-03 to identify that the overall dashboard shows 62 percent package progress, the A-314 dashboard tile shows 65 percent, the baseline expected 70 percent, and the daily progress input supports only 48 percent actual, confirm float moved from +3 to -2 days, decide that the A-314 dashboard status is Not Ready for unsupported release, and complete Evidence Validation Checklist fields Evidence Status, Conflict Noted, Missing Evidence, and Reviewer Question. The challenge is that a clean dashboard graphic may hide weak source evidence.', '["overall dashboard 62 percent, A-314 dashboard 65 percent, baseline planned 70 percent, daily progress actual 48 percent, float -2 days, source link blank"]'::jsonb, '["Safe: Mark conflicting and missing evidence, cite exact evidence IDs, and ask for the missing source record.", "Risky: Accept the dashboard percentage because it is formatted for the review meeting.", "Escalation: Escalate if the package owner asks for release while A-314 evidence remains inconsistent.", "Outside-role: approve baseline/EOT/client-ready release", "AI misuse: ask AI to complete artifact."]'::jsonb, 'In this module, the learner must use E-M2-01, E-M2-02, and E-M2-03 to identify that the overall dashboard shows 62 percent package progress, the A-314 dashboard tile shows 65 percent, the baseline expected 70 percent, and the daily progress input supports only 48 percent actual, confirm float moved from +3 to -2 days, decide that the A-314 dashboard status is Not Ready for unsupported release, and complete Evidence Validation Checklist fields Evidence Status, Conflict Noted, Missing Evidence, and Reviewer Question. The challenge is that a clean dashboard graphic may hide weak source evidence.', '["Case Intake Note"]'::jsonb, '["Use E-M2-01, E-M2-02, E-M2-03 to complete Evidence Validation Checklist while preserving L1 authority."]'::jsonb, 'Use before handing off to Action or Handoff Note in the HN-24A weekly review workflow.', '{"major_concepts": "Evidence IDs: E-M2-01, E-M2-02, E-M2-03", "key_data": "overall dashboard 62 percent, A-314 dashboard 65 percent, baseline planned 70 percent, daily progress actual 48 percent, float -2 days, source link blank", "implementation_context_when_to_use": "Use before handing off to Action or Handoff Note in the HN-24A weekly review workflow.", "reason_behind_concept": "supports evidence-led progress, schedule and recovery-control decisions at L1."}'::jsonb, '{"ai_support_tips": "Think-first AI gate: AI unlocks only after learner writes first judgment and cites E-M2-01. Retry: Revise Evidence Status, Conflict Noted, Missing Evidence, and Reviewer Question after rechecking E-M2-01 and E-M2-02."}'::jsonb, '{"evidence_ids": "E-M2-01, E-M2-02, E-M2-03", "key_data": "overall dashboard 62 percent, A-314 dashboard 65 percent, baseline planned 70 percent, daily progress actual 48 percent, float -2 days, source link blank"}'::jsonb, 'At L1, complete Evidence Validation Checklist using traceable project-control evidence while preserving the level decision boundary.', '{"items": ["Schedule / programme", "DPR / daily record", "progress dashboard", "evidence tracker", "recovery / escalation record", "spreadsheet artifact"]}'::jsonb, TRUE, TRUE)
