VALUES ('82fc5fb8-4cc8-53e8-a8de-4149ce449739'::uuid, '029f3de1-70b8-5b3f-9203-6f5cee8be5f5'::uuid, 3, 'Guided Work Action / Handoff', 'In this module, the learner must use E-M3-01, E-M3-02, and E-M3-03 to identify the rain/site-access delay, rebar delivery delay, and critical-path shift to -2 days float, decide the safe handoff action, and complete Action or Handoff Note fields Variance Summary, Evidence Basis, Proposed Next Action, Owner Needed, and Boundary Statement. The challenge is that the recovery option note includes an outside-role ''approve resequence'' phrase that may tempt the learner to decide instead of hand off.', '["access delay 1.5 days, PO-RB-447 received 2026-07-06, float from +3 to -2, RA-17 owner blank"]'::jsonb, '["Safe: Prepare a handoff note with evidence-backed variance and request planning engineer decision.", "Risky: Recommend baseline resequencing or approve recovery dates without supervisor review.", "Escalation: Escalate missing recovery owner and negative float to the planning engineer before the review.", "Outside-role: approve baseline/EOT/client-ready release", "AI misuse: ask AI to complete artifact."]'::jsonb, 'In this module, the learner must use E-M3-01, E-M3-02, and E-M3-03 to identify the rain/site-access delay, rebar delivery delay, and critical-path shift to -2 days float, decide the safe handoff action, and complete Action or Handoff Note fields Variance Summary, Evidence Basis, Proposed Next Action, Owner Needed, and Boundary Statement. The challenge is that the recovery option note includes an outside-role ''approve resequence'' phrase that may tempt the learner to decide instead of hand off.', '["Evidence Validation Checklist"]'::jsonb, '["Use E-M3-01, E-M3-02, E-M3-03 to complete Action or Handoff Note while preserving L1 authority."]'::jsonb, 'Use before handing off to Risk and Escalation Note in the HN-24A weekly review workflow.', '{"major_concepts": "Evidence IDs: E-M3-01, E-M3-02, E-M3-03", "key_data": "access delay 1.5 days, PO-RB-447 received 2026-07-06, float from +3 to -2, RA-17 owner blank", "implementation_context_when_to_use": "Use before handing off to Risk and Escalation Note in the HN-24A weekly review workflow.", "reason_behind_concept": "supports evidence-led progress, schedule and recovery-control decisions at L1."}'::jsonb, '{"ai_support_tips": "Think-first AI gate: AI unlocks only after learner writes first judgment and cites E-M3-01. Retry: Revise Proposed Next Action, Owner Needed, and Boundary Statement after rechecking E-M3-02 critical-path snapshot."}'::jsonb, '{"evidence_ids": "E-M3-01, E-M3-02, E-M3-03", "key_data": "access delay 1.5 days, PO-RB-447 received 2026-07-06, float from +3 to -2, RA-17 owner blank"}'::jsonb, 'At L1, complete Action or Handoff Note using traceable project-control evidence while preserving the level decision boundary.', '{"items": ["Schedule / programme", "DPR / daily record", "progress dashboard", "evidence tracker", "recovery / escalation record", "spreadsheet artifact"]}'::jsonb, TRUE, TRUE)
