VALUES ('62ec0bb6-d67f-580d-bf53-b0cb7dcfaefc'::uuid, '029f3de1-70b8-5b3f-9203-6f5cee8be5f5'::uuid, 4, 'Exceptions, Blockers, Risks & Escalation', 'In this module, the learner must use E-M4-01, E-M4-02, and E-M4-03 to identify missing owner for rebar PO-RB-447, 1.5-day site access blockage, and negative float risk, decide the correct escalation route, and complete Risk and Escalation Note fields Blocker Type, Risk Signal, Escalation Owner, Due Date, Evidence Attached, and Consequence. The challenge is that the procurement tracker says ''delivered'' while the site access log shows work still could not proceed.', '["GRN pending, work permit reopened 2026-07-06 14:00, QA walkthrough pending, do-not-mark-recovered note"]'::jsonb, '["Safe: Escalate blocker with evidence IDs, missing owner, due date, and review impact.", "Risky: Close the blocker because the material tracker says delivered.", "Escalation: Route unresolved owner and access issue to planning engineer with procurement and site supervisor copied.", "Outside-role: approve baseline/EOT/client-ready release", "AI misuse: ask AI to complete artifact."]'::jsonb, 'In this module, the learner must use E-M4-01, E-M4-02, and E-M4-03 to identify missing owner for rebar PO-RB-447, 1.5-day site access blockage, and negative float risk, decide the correct escalation route, and complete Risk and Escalation Note fields Blocker Type, Risk Signal, Escalation Owner, Due Date, Evidence Attached, and Consequence. The challenge is that the procurement tracker says ''delivered'' while the site access log shows work still could not proceed.', '["Action or Handoff Note"]'::jsonb, '["Use E-M4-01, E-M4-02, E-M4-03 to complete Risk and Escalation Note while preserving L1 authority."]'::jsonb, 'Use before handing off to Quality and Closure Report in the HN-24A weekly review workflow.', '{"major_concepts": "Evidence IDs: E-M4-01, E-M4-02, E-M4-03", "key_data": "GRN pending, work permit reopened 2026-07-06 14:00, QA walkthrough pending, do-not-mark-recovered note", "implementation_context_when_to_use": "Use before handing off to Quality and Closure Report in the HN-24A weekly review workflow.", "reason_behind_concept": "supports evidence-led progress, schedule and recovery-control decisions at L1."}'::jsonb, '{"ai_support_tips": "Think-first AI gate: AI unlocks only after learner writes first judgment and cites E-M4-01. Retry: Revise Blocker Type, Escalation Owner, Evidence Attached, and Consequence after rechecking E-M4-02 and E-M4-03."}'::jsonb, '{"evidence_ids": "E-M4-01, E-M4-02, E-M4-03", "key_data": "GRN pending, work permit reopened 2026-07-06 14:00, QA walkthrough pending, do-not-mark-recovered note"}'::jsonb, 'At L1, complete Risk and Escalation Note using traceable project-control evidence while preserving the level decision boundary.', '{"items": ["Schedule / programme", "DPR / daily record", "progress dashboard", "evidence tracker", "recovery / escalation record", "spreadsheet artifact"]}'::jsonb, TRUE, TRUE)
