VALUES ('e232b645-28fd-5460-a0c3-06338199c43b'::uuid, '029f3de1-70b8-5b3f-9203-6f5cee8be5f5'::uuid, 5, 'Quality Review, Communication & Closure', 'In this module, the learner must use E-M5-01, E-M5-02, and E-M5-03 to identify missing evidence attachment E-M2-02, missing owner for recovery action RA-17, and unsupported closure wording, decide that the closure report needs revision, and complete Quality and Closure Report fields Evidence Trail Complete, Open Risks, Communication Draft, Closure Status, and Retry Log. The challenge is that the handoff draft sounds polished but lacks the source evidence needed for review.', '["E-M2-02 missing from draft, RA-17 owner blank, ''client-ready'' wording rejected, Pending Planning Engineer Review"]'::jsonb, '["Safe: Revise closure to ''Pending Planning Engineer Review'' and attach source evidence IDs.", "Risky: Send ''ready for client review'' because the communication draft is well written.", "Escalation: Request supervisor review for closure language when evidence remains open.", "Outside-role: approve baseline/EOT/client-ready release", "AI misuse: ask AI to complete artifact."]'::jsonb, 'In this module, the learner must use E-M5-01, E-M5-02, and E-M5-03 to identify missing evidence attachment E-M2-02, missing owner for recovery action RA-17, and unsupported closure wording, decide that the closure report needs revision, and complete Quality and Closure Report fields Evidence Trail Complete, Open Risks, Communication Draft, Closure Status, and Retry Log. The challenge is that the handoff draft sounds polished but lacks the source evidence needed for review.', '["Risk and Escalation Note"]'::jsonb, '["Use E-M5-01, E-M5-02, E-M5-03 to complete Quality and Closure Report while preserving L1 authority."]'::jsonb, 'Use before handing off to Final Portfolio Pack in the HN-24A weekly review workflow.', '{"major_concepts": "Evidence IDs: E-M5-01, E-M5-02, E-M5-03", "key_data": "E-M2-02 missing from draft, RA-17 owner blank, ''client-ready'' wording rejected, Pending Planning Engineer Review", "implementation_context_when_to_use": "Use before handing off to Final Portfolio Pack in the HN-24A weekly review workflow.", "reason_behind_concept": "supports evidence-led progress, schedule and recovery-control decisions at L1."}'::jsonb, '{"ai_support_tips": "Think-first AI gate: AI unlocks only after learner writes first judgment and cites E-M5-01. Retry: Revise Evidence Trail Complete, Communication Draft, Closure Status, and Retry Log after rechecking E-M5-01 and E-M5-03."}'::jsonb, '{"evidence_ids": "E-M5-01, E-M5-02, E-M5-03", "key_data": "E-M2-02 missing from draft, RA-17 owner blank, ''client-ready'' wording rejected, Pending Planning Engineer Review"}'::jsonb, 'At L1, complete Quality and Closure Report using traceable project-control evidence while preserving the level decision boundary.', '{"items": ["Schedule / programme", "DPR / daily record", "progress dashboard", "evidence tracker", "recovery / escalation record", "spreadsheet artifact"]}'::jsonb, TRUE, TRUE)
