VALUES ('2390a5d6-c5a3-5b41-ab45-a95d1f9f44e9'::uuid, '029f3de1-70b8-5b3f-9203-6f5cee8be5f5'::uuid, 6, 'Portfolio, Transfer & Final Validation', 'In this module, the learner must use E-M6-01, E-M6-02, and E-M6-03 to verify that the artifact chain is complete, retry corrections are visible, and a second package can be classified without approval overclaim, decide whether the portfolio is certification-ready, and complete Final Portfolio Pack fields Artifact Chain, Evidence Index, Retry Corrections, Transfer Explanation, Boundary Defense, and Reviewer Questions. The challenge is that the transfer case includes a tempting ''approve updated baseline'' request beyond L1 authority.', '["seven artifacts required, M5 retry screenshot missing, B-209 planned 55 actual 54, baseline approval request outside L1"]'::jsonb, '["Safe: Submit a portfolio with all artifacts, evidence IDs, retry record, transfer explanation, and boundary defense.", "Risky: Claim the learner can approve recovery or baseline changes because the artifacts are complete.", "Escalation: Ask human reviewer to validate unresolved SME clause references and boundary wording.", "Outside-role: approve baseline/EOT/client-ready release", "AI misuse: ask AI to complete artifact."]'::jsonb, 'In this module, the learner must use E-M6-01, E-M6-02, and E-M6-03 to verify that the artifact chain is complete, retry corrections are visible, and a second package can be classified without approval overclaim, decide whether the portfolio is certification-ready, and complete Final Portfolio Pack fields Artifact Chain, Evidence Index, Retry Corrections, Transfer Explanation, Boundary Defense, and Reviewer Questions. The challenge is that the transfer case includes a tempting ''approve updated baseline'' request beyond L1 authority.', '["Quality and Closure Report plus all prior artifacts"]'::jsonb, '["Use E-M6-01, E-M6-02, E-M6-03 to complete Final Portfolio Pack while preserving L1 authority."]'::jsonb, 'Use before handing off to Certification review in the HN-24A weekly review workflow.', '{"major_concepts": "Evidence IDs: E-M6-01, E-M6-02, E-M6-03", "key_data": "seven artifacts required, M5 retry screenshot missing, B-209 planned 55 actual 54, baseline approval request outside L1", "implementation_context_when_to_use": "Use before handing off to Certification review in the HN-24A weekly review workflow.", "reason_behind_concept": "supports evidence-led progress, schedule and recovery-control decisions at L1."}'::jsonb, '{"ai_support_tips": "Think-first AI gate: AI unlocks only after learner writes first judgment and cites E-M6-01. Retry: Revise Artifact Chain, Retry Corrections, Transfer Explanation, and Boundary Defense after rechecking E-M6-01 and E-M6-02."}'::jsonb, '{"evidence_ids": "E-M6-01, E-M6-02, E-M6-03", "key_data": "seven artifacts required, M5 retry screenshot missing, B-209 planned 55 actual 54, baseline approval request outside L1"}'::jsonb, 'At L1, complete Final Portfolio Pack using traceable project-control evidence while preserving the level decision boundary.', '{"items": ["Schedule / programme", "DPR / daily record", "progress dashboard", "evidence tracker", "recovery / escalation record", "spreadsheet artifact"]}'::jsonb, TRUE, TRUE)
